const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const keukenhof = ee.Geometry.Point([4.546, 52.270]);
  const roi = keukenhof.buffer(500); // 500m radius around Keukenhof

  const date1 = ee.Date('2018-04-21');
  const date2 = ee.Date('2018-05-07');

  // 2. Data Acquisition & Check
  function maskClouds(image) {
    const scl = image.select('SCL');
    const mask = scl.neq(3).and(scl.neq(8)).and(scl.neq(9)).and(scl.neq(10));
    return image.updateMask(mask);
  }

  function detectRedFlowers(image) {
    const red = image.select('B4');
    const green = image.select('B3');
    const blue = image.select('B2');

    // Red flowers: R > G and R > B and R > 1500 (to avoid bare soil)
    const redMask = red.gt(green)
                      .and(red.gt(blue))
                      .and(red.gt(1500))
                      .and(green.lt(2000)); // Avoid bright white/clouds

    return image.updateMask(redMask);
  }

  // Get images for April 21
  let col1 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(roi)
    .filterDate(date1.advance(-3, 'day'), date1.advance(3, 'day'))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

  const size1 = col1.size().getInfo();
  console.log(`April 21 images found: ${size1}`);

  if (size1 === 0) {
    console.log('No images for April 21, 2018');
    console.log('<answer>C1</answer>');
    return;
  }

  // Get images for May 7
  let col2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(roi)
    .filterDate(date2.advance(-3, 'day'), date2.advance(3, 'day'))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

  const size2 = col2.size().getInfo();
  console.log(`May 7 images found: ${size2}`);

  if (size2 === 0) {
    console.log('No images for May 7, 2018');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing
  const img1 = maskClouds(col1.first());
  const img2 = maskClouds(col2.first());

  // Count valid pixels after cloud masking
  const validCount1 = img1.select('B4').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 10,
    maxPixels: 1e9
  }).get('B4').getInfo();

  const validCount2 = img2.select('B4').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 10,
    maxPixels: 1e9
  }).get('B4').getInfo();

  console.log(`April 21 valid pixels: ${validCount1}`);
  console.log(`May 7 valid pixels: ${validCount2}`);

  if (validCount1 === 0 || validCount2 === 0) {
    console.log('No valid pixels after cloud masking');
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Detect and count red flowers
  const redImg1 = detectRedFlowers(img1);
  const redImg2 = detectRedFlowers(img2);

  const redCount1 = redImg1.select('B4').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 10,
    maxPixels: 1e9
  }).get('B4').getInfo();

  const redCount2 = redImg2.select('B4').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 10,
    maxPixels: 1e9
  }).get('B4').getInfo();

  // 5. Validation & Final Answer
  console.log(`April 21 red flower pixels: ${redCount1}`);
  console.log(`May 7 red flower pixels: ${redCount2}`);

  if (redCount1 === null || redCount2 === null) {
    console.log('Calculation failed');
    console.log('<answer>C3</answer>');
    return;
  }

  if (redCount1 > redCount2) {
    console.log('More red flowers on April 21');
    console.log('<answer>A</answer>');
  } else {
    console.log('More or equal red flowers on May 7');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
